mapper.select:
        /*bill.getCurPrevMonthBill*/
SELECT (
              -- 현재월 AWS 데이터
              SELECT COALESCE(SUM(ms.total_cost), 0)
                FROM monthly_summation ms
               WHERE ms.year_month = #{curYearMonth}

                 AND ms.csp IN

                     #{selectedCsp}


                 AND ms.project_cd IN

                     #{selectedProject}

              ) + (
              -- 현재월 NCP VM 데이터 (VM별 최신 누적 금액만 반영)
              SELECT COALESCE(SUM(nvd_latest.demand_amount), 0) / ${krwPerUsd}
                FROM (
                    SELECT n1.instance_no, n1.demand_amount
                    FROM ncp_cost_vm_month n1
                    INNER JOIN (
                        SELECT instance_no, MAX(id) AS latest_id
                        FROM ncp_cost_vm_month
                        WHERE demand_month = #{curYearMonth}
                        GROUP BY instance_no
                    ) n2
                    ON n1.instance_no = n2.instance_no
                    AND n1.id = n2.latest_id
                ) nvd_latest
          INNER JOIN servicegroup_meta sm
               ON nvd_latest.instance_no COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
              AND sm.csp_type = 'NCP'
            WHERE 1=1

                 AND sm.service_cd IN

                     #{selectedProject}



                 AND 1=0

              ) + (
              -- 현재월 Azure VM 데이터 (조인 후 계산)
              SELECT COALESCE(SUM(acvd.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_vm_daily acvd
               INNER JOIN servicegroup_meta sm
                  ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
                 AND sm.csp_type = 'AZURE'

                 AND sm.service_cd IN

                     #{selectedProject}


               WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{curYearMonth}

                 AND 1=0

              ) + (
              -- 현재월 Azure K8S/Object Storage 데이터 (azure_cost_resource_daily, 조인 후 계산)
              SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_resource_daily acr
               INNER JOIN servicegroup_meta sm
                  ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci
                 AND sm.csp_type = 'AZURE'
                 AND acr.resource_type != 'OBJECT_STORAGE'  -- Object Storage 는 계정 단위 블록(D-4)에서 집계

                 AND sm.service_cd IN

                     #{selectedProject}


               WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{curYearMonth}

                 AND 1=0

              ) + (
              -- 현재월 D-4: Azure Object Storage — Storage Account 단위 행(계정 매핑 ${azureObjStgAccounts}), Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함
              SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_resource_daily acr
               WHERE acr.resource_type = 'OBJECT_STORAGE'
                 AND LOWER(acr.resource_name) IN (${azureObjStgAccounts})
                 AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{curYearMonth}
                 AND EXISTS (SELECT 1 FROM servicegroup_meta smo
                              WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'

                                AND smo.service_cd IN

                                  #{selectedProject}


                            )

                   AND 1=0

              ) + (
              -- 현재월 NCP K8S/Object Storage 데이터 (ncp_cost_resource_month, 자원·상세코드·계약별 최신 누적 금액만 반영)
              SELECT COALESCE(SUM(nr_latest.demand_amount), 0) / ${krwPerUsd}
         FROM (
              SELECT n1.resource_id, n1.resource_type, n1.member_no, n1.demand_month, n1.demand_amount
                FROM ncp_cost_resource_month n1
               INNER JOIN (
                     SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id
                       FROM ncp_cost_resource_month
                      WHERE demand_month = #{curYearMonth}
                      GROUP BY resource_id, demand_type_detail_code, contract_no
                     ) n2
                  ON n1.resource_id = n2.resource_id
                 AND n1.demand_type_detail_code = n2.demand_type_detail_code
                 AND n1.contract_no = n2.contract_no
                 AND n1.id = n2.latest_id
                 AND n1.resource_type != 'OBJECT_STORAGE'  -- Object Storage 는 계정 단위 블록(D-4)에서 집계
              ) nr_latest
        INNER JOIN servicegroup_meta sm
           ON nr_latest.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
          AND sm.csp_type = 'NCP'
            WHERE 1=1

                 AND sm.service_cd IN

                     #{selectedProject}



                 AND 1=0

              ) + (
              -- 현재월 D-4: NCP Object Storage — 계정 단위(OSSM) 행, 최신 누적 스냅샷, Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함
              SELECT COALESCE(SUM(nro.demand_amount), 0) / ${krwPerUsd}
                FROM (
                     SELECT o1.resource_id, o1.resource_type, o1.member_no, o1.demand_month, o1.demand_amount
                       FROM ncp_cost_resource_month o1
                      INNER JOIN (
                            SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id
                              FROM ncp_cost_resource_month
                             WHERE demand_month = #{curYearMonth}
                               AND resource_type = 'OBJECT_STORAGE'
                             GROUP BY resource_id, demand_type_detail_code, contract_no
                            ) o2
                      ON o1.resource_id = o2.resource_id
                     AND o1.demand_type_detail_code = o2.demand_type_detail_code
                     AND o1.contract_no = o2.contract_no
                     AND o1.id = o2.latest_id
                     ) nro
                WHERE nro.resource_type = 'OBJECT_STORAGE'
                  AND EXISTS (SELECT 1 FROM servicegroup_meta smo
                               WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'

                                 AND smo.service_cd IN

                                   #{selectedProject}


                             )

                    AND 1=0

              ) AS curMonthBill,

       (
              -- 이전월 AWS 데이터
              SELECT COALESCE(SUM(ms.total_cost), 0)
                FROM monthly_summation ms
               WHERE ms.year_month = #{prevYearMonth}

                 AND ms.csp IN

                     #{selectedCsp}


                 AND ms.project_cd IN

                     #{selectedProject}

              ) + (
              -- 이전월 NCP VM 데이터 (VM별 최신 누적 금액만 반영)
                SELECT COALESCE(SUM(nvd_latest.demand_amount), 0) / ${krwPerUsd}
                  FROM (
                    SELECT n1.instance_no, n1.demand_amount
                    FROM ncp_cost_vm_month n1
                    INNER JOIN (
                        SELECT instance_no, MAX(id) AS latest_id
                        FROM ncp_cost_vm_month
                        WHERE demand_month = #{prevYearMonth}
                        GROUP BY instance_no
                    ) n2
                    ON n1.instance_no = n2.instance_no
                    AND n1.id = n2.latest_id
                ) nvd_latest
            INNER JOIN servicegroup_meta sm
                    ON nvd_latest.instance_no COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
                   AND sm.csp_type = 'NCP'
                 WHERE 1=1

                   AND sm.service_cd IN

                    #{selectedProject}



                AND 1=0

              ) + (
              -- 이전월 Azure VM 데이터 (조인 후 계산)
              SELECT COALESCE(SUM(acvd.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_vm_daily acvd
               INNER JOIN servicegroup_meta sm
                  ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
                 AND sm.csp_type = 'AZURE'

                 AND sm.service_cd IN

                     #{selectedProject}


               WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{prevYearMonth}

                 AND 1=0

              ) + (
              -- 이전월 Azure K8S/Object Storage 데이터 (azure_cost_resource_daily, 조인 후 계산)
              SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_resource_daily acr
               INNER JOIN servicegroup_meta sm
                  ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci
                 AND sm.csp_type = 'AZURE'
                 AND acr.resource_type != 'OBJECT_STORAGE'  -- Object Storage 는 계정 단위 블록(D-4)에서 집계

                 AND sm.service_cd IN

                     #{selectedProject}


               WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{prevYearMonth}

                 AND 1=0

              ) + (
              -- 이전월 D-4: Azure Object Storage — Storage Account 단위 행(계정 매핑 ${azureObjStgAccounts}), Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함
              SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd}
                FROM azure_cost_resource_daily acr
               WHERE acr.resource_type = 'OBJECT_STORAGE'
                 AND LOWER(acr.resource_name) IN (${azureObjStgAccounts})
                 AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{prevYearMonth}
                 AND EXISTS (SELECT 1 FROM servicegroup_meta smo
                              WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'

                                AND smo.service_cd IN

                                  #{selectedProject}


                            )

                   AND 1=0

              ) + (
              -- 이전월 NCP K8S/Object Storage 데이터 (ncp_cost_resource_month, 자원·상세코드·계약별 최신 누적 금액만 반영)
              SELECT COALESCE(SUM(nr_latest.demand_amount), 0) / ${krwPerUsd}
         FROM (
              SELECT n1.resource_id, n1.resource_type, n1.member_no, n1.demand_month, n1.demand_amount
                FROM ncp_cost_resource_month n1
               INNER JOIN (
                     SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id
                       FROM ncp_cost_resource_month
                      WHERE demand_month = #{prevYearMonth}
                      GROUP BY resource_id, demand_type_detail_code, contract_no
                     ) n2
                  ON n1.resource_id = n2.resource_id
                 AND n1.demand_type_detail_code = n2.demand_type_detail_code
                 AND n1.contract_no = n2.contract_no
                 AND n1.id = n2.latest_id
                 AND n1.resource_type != 'OBJECT_STORAGE'  -- Object Storage 는 계정 단위 블록(D-4)에서 집계
              ) nr_latest
        INNER JOIN servicegroup_meta sm
           ON nr_latest.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci
          AND sm.csp_type = 'NCP'
            WHERE 1=1

                 AND sm.service_cd IN

                     #{selectedProject}



                 AND 1=0

              ) + (
              -- 이전월 D-4: NCP Object Storage — 계정 단위(OSSM) 행, 최신 누적 스냅샷, Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함
              SELECT COALESCE(SUM(nro.demand_amount), 0) / ${krwPerUsd}
                FROM (
                     SELECT o1.resource_id, o1.resource_type, o1.member_no, o1.demand_month, o1.demand_amount
                       FROM ncp_cost_resource_month o1
                      INNER JOIN (
                            SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id
                              FROM ncp_cost_resource_month
                             WHERE demand_month = #{prevYearMonth}
                               AND resource_type = 'OBJECT_STORAGE'
                             GROUP BY resource_id, demand_type_detail_code, contract_no
                            ) o2
                      ON o1.resource_id = o2.resource_id
                     AND o1.demand_type_detail_code = o2.demand_type_detail_code
                     AND o1.contract_no = o2.contract_no
                     AND o1.id = o2.latest_id
                     ) nro
                WHERE nro.resource_type = 'OBJECT_STORAGE'
                  AND EXISTS (SELECT 1 FROM servicegroup_meta smo
                               WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'

                                 AND smo.service_cd IN

                                   #{selectedProject}


                             )

                    AND 1=0

              ) AS prevMonthBill

/*bill.getMonthBill*/ SELECT ym.`year_month` , SUBSTRING(ym.`year_month`, 1, 4) AS `year` , SUBSTRING(ym.`year_month`, 5, 2) AS `month` , COALESCE(SUM(all_data.total_cost), 0) AS bill FROM (
SELECT #{prevMonth} COLLATE utf8mb4_unicode_ci AS `year_month`
) AS ym LEFT JOIN ( -- AWS 데이터 SELECT ms.`year_month` COLLATE utf8mb4_unicode_ci AS `year_month` , SUM(ms.total_cost) AS total_cost FROM monthly_summation ms WHERE ms.project_cd IN
#{selectedProject}
AND ms.csp IN
#{selectedCsp}
AND ms.`year_month` IN
#{prevMonth}
GROUP BY ms.`year_month`
UNION ALL
-- NCP VM 데이터 (VM별 월별 최신 누적 금액만 반영) SELECT nvd_latest.demand_month COLLATE utf8mb4_unicode_ci AS `year_month`, SUM(nvd_latest.demand_amount) / ${krwPerUsd} AS total_cost FROM ( SELECT n1.demand_month, n1.instance_no, n1.demand_amount FROM ncp_cost_vm_month n1 INNER JOIN ( SELECT demand_month, instance_no, MAX(id) AS latest_id FROM ncp_cost_vm_month WHERE demand_month IN
#{prevMonth}
GROUP BY demand_month, instance_no ) n2 ON n1.demand_month = n2.demand_month AND n1.instance_no = n2.instance_no AND n1.id = n2.latest_id ) nvd_latest INNER JOIN servicegroup_meta sm ON nvd_latest.instance_no COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP'
AND sm.service_cd IN
#{selectedProject}
AND 1=0
GROUP BY nvd_latest.demand_month
UNION ALL
-- Azure VM 데이터 (servicegroup_meta 조인 후 필터링) SELECT DATE_FORMAT(acvd.usage_date, '%Y%m') COLLATE utf8mb4_unicode_ci AS `year_month` , SUM(acvd.pre_tax_cost) / ${krwPerUsd} AS total_cost FROM azure_cost_vm_daily acvd INNER JOIN servicegroup_meta sm ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE'
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') IN
#{prevMonth}
AND 1=0
GROUP BY DATE_FORMAT(acvd.usage_date, '%Y%m')
UNION ALL
-- Azure K8S/Object Storage 데이터 (azure_cost_resource_daily, servicegroup_meta 조인 후 필터링) SELECT DATE_FORMAT(acr.usage_date, '%Y%m') COLLATE utf8mb4_unicode_ci AS `year_month` , SUM(acr.pre_tax_cost) / ${krwPerUsd} AS total_cost FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계
AND sm.service_cd IN
#{selectedProject}
WHERE DATE_FORMAT(acr.usage_date, '%Y%m') IN
#{prevMonth}
AND 1=0
GROUP BY DATE_FORMAT(acr.usage_date, '%Y%m')
UNION ALL
-- D-4: Azure Object Storage — Storage Account 단위 행(계정 매핑 ${azureObjStgAccounts}), Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT DATE_FORMAT(acr.usage_date, '%Y%m') COLLATE utf8mb4_unicode_ci AS `year_month` , SUM(acr.pre_tax_cost) / ${krwPerUsd} AS total_cost FROM azure_cost_resource_daily acr WHERE acr.resource_type = 'OBJECT_STORAGE' AND LOWER(acr.resource_name) IN (${azureObjStgAccounts}) AND DATE_FORMAT(acr.usage_date, '%Y%m') IN
#{prevMonth}
AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
AND 1=0
GROUP BY DATE_FORMAT(acr.usage_date, '%Y%m')
UNION ALL
-- NCP K8S/Object Storage 데이터 (ncp_cost_resource_month, 자원·상세코드·계약별 월별 최신 누적 금액만 반영) SELECT nr_latest.demand_month COLLATE utf8mb4_unicode_ci AS `year_month`, SUM(nr_latest.demand_amount) / ${krwPerUsd} AS total_cost FROM ( SELECT n1.demand_month, n1.resource_id, n1.demand_amount FROM ncp_cost_resource_month n1 INNER JOIN ( SELECT demand_month, resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month IN
#{prevMonth}
GROUP BY demand_month, resource_id, demand_type_detail_code, contract_no ) n2 ON n1.demand_month = n2.demand_month AND n1.resource_id = n2.resource_id AND n1.demand_type_detail_code = n2.demand_type_detail_code AND n1.contract_no = n2.contract_no AND n1.id = n2.latest_id AND n1.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 ) nr_latest INNER JOIN servicegroup_meta sm ON nr_latest.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP'
AND sm.service_cd IN
#{selectedProject}
AND 1=0
GROUP BY nr_latest.demand_month
UNION ALL
-- D-4: NCP Object Storage — 계정 단위(OSSM) 행, 최신 누적 스냅샷, Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT nro.demand_month COLLATE utf8mb4_unicode_ci AS `year_month` , SUM(nro.demand_amount) / ${krwPerUsd} AS total_cost FROM ( SELECT o1.resource_id, o1.resource_type, o1.member_no, o1.demand_month, o1.demand_amount FROM ncp_cost_resource_month o1 INNER JOIN ( SELECT demand_month, resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month IN
#{prevMonth}
AND resource_type = 'OBJECT_STORAGE' GROUP BY demand_month, resource_id, demand_type_detail_code, contract_no ) o2 ON o1.demand_month = o2.demand_month AND o1.resource_id = o2.resource_id AND o1.demand_type_detail_code = o2.demand_type_detail_code AND o1.contract_no = o2.contract_no AND o1.id = o2.latest_id ) nro WHERE nro.resource_type = 'OBJECT_STORAGE' AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
AND 1=0
GROUP BY nro.demand_month ) AS all_data ON ym.`year_month` = all_data.`year_month` GROUP BY ym.`year_month` ORDER BY ym.`year_month` DESC

SELECT service_name AS resourceNm , SUM(total_cost) AS bill , csp FROM (
SELECT CASE WHEN sm.service_type = 'K8S' THEN 'AmazonEKS' ELSE co.lineitem_productcode END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(co.lineitem_unblendedcost), 0) AS total_cost , 'AWS' COLLATE utf8mb4_unicode_ci AS csp FROM tbl_table_billing_detail_${year_month} co LEFT JOIN servicegroup_meta sm ON co.lineitem_resourceid = sm.csp_instanceid WHERE sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
GROUP BY CASE WHEN sm.service_type = 'K8S' THEN 'AmazonEKS' ELSE co.lineitem_productcode END
UNION ALL
SELECT CASE WHEN sm.service_type = 'VM' THEN 'Virtual Machine' ELSE sm.service_type END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(acvd.pre_tax_cost), 0) / ${krwPerUsd} AS total_cost , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_vm_daily acvd INNER JOIN servicegroup_meta sm ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
#{selectedProject}
GROUP BY CASE WHEN sm.service_type = 'VM' THEN 'Virtual Machine' ELSE sm.service_type END
UNION ALL
SELECT CASE acr.resource_type WHEN 'K8S' THEN 'Azure Kubernetes Service' WHEN 'K8S_NODE' THEN 'Azure Kubernetes Service' -- AKS 노드 스케일셋도 AKS 로 합산 WHEN 'OBJECT_STORAGE' THEN 'Storage' ELSE acr.resource_type END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS total_cost , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
#{selectedProject}
GROUP BY CASE acr.resource_type WHEN 'K8S' THEN 'Azure Kubernetes Service' WHEN 'K8S_NODE' THEN 'Azure Kubernetes Service' WHEN 'OBJECT_STORAGE' THEN 'Storage' ELSE acr.resource_type END
UNION ALL
SELECT 'Storage' COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS total_cost , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_resource_daily acr WHERE acr.resource_type = 'OBJECT_STORAGE' AND LOWER(acr.resource_name) IN (${azureObjStgAccounts}) AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month} AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
UNION ALL
SELECT CASE WHEN sm.service_type = 'VM' THEN 'Server' WHEN sm.service_type = 'K8S' THEN 'Kubernetes Service' -- NKS 노드 서버 비용은 NKS 관리비 줄과 합산 ELSE sm.service_type END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(vm_latest.demand_amount), 0) / ${krwPerUsd} AS total_cost , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ( SELECT n1.instance_no, n1.demand_amount FROM ncp_cost_vm_month n1 INNER JOIN ( SELECT instance_no, MAX(id) AS latest_id FROM ncp_cost_vm_month WHERE demand_month = #{year_month} GROUP BY instance_no ) n2 ON n1.instance_no = n2.instance_no AND n1.id = n2.latest_id ) vm_latest INNER JOIN servicegroup_meta sm ON vm_latest.instance_no COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
GROUP BY CASE WHEN sm.service_type = 'VM' THEN 'Server' WHEN sm.service_type = 'K8S' THEN 'Kubernetes Service' ELSE sm.service_type END
UNION ALL
SELECT CASE nr_latest.resource_type WHEN 'K8S' THEN 'Kubernetes Service' WHEN 'OBJECT_STORAGE' THEN 'Object Storage' ELSE nr_latest.resource_type END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(nr_latest.demand_amount), 0) / ${krwPerUsd} AS total_cost , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ( SELECT n1.resource_id, n1.resource_type, n1.member_no, n1.demand_month, n1.demand_amount FROM ncp_cost_resource_month n1 INNER JOIN ( SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month = #{year_month} GROUP BY resource_id, demand_type_detail_code, contract_no ) n2 ON n1.resource_id = n2.resource_id AND n1.demand_type_detail_code = n2.demand_type_detail_code AND n1.contract_no = n2.contract_no AND n1.id = n2.latest_id AND n1.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 ) nr_latest INNER JOIN servicegroup_meta sm ON nr_latest.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
GROUP BY CASE nr_latest.resource_type WHEN 'K8S' THEN 'Kubernetes Service' WHEN 'OBJECT_STORAGE' THEN 'Object Storage' ELSE nr_latest.resource_type END UNION ALL
SELECT 'Object Storage' COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(nro.demand_amount), 0) / ${krwPerUsd} AS total_cost , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ( SELECT o1.resource_id, o1.resource_type, o1.member_no, o1.demand_month, o1.demand_amount FROM ncp_cost_resource_month o1 INNER JOIN ( SELECT resource_id, demand_type_detail_code, contract_no, MAX(id) AS latest_id FROM ncp_cost_resource_month WHERE demand_month = #{year_month} AND resource_type = 'OBJECT_STORAGE' GROUP BY resource_id, demand_type_detail_code, contract_no ) o2 ON o1.resource_id = o2.resource_id AND o1.demand_type_detail_code = o2.demand_type_detail_code AND o1.contract_no = o2.contract_no AND o1.id = o2.latest_id ) nro WHERE nro.resource_type = 'OBJECT_STORAGE' AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
UNION ALL
SELECT CASE WHEN sm.service_type = 'K8S' THEN 'Kubernetes Engine' ELSE raw.service_description END COLLATE utf8mb4_unicode_ci AS service_name , COALESCE(SUM(raw.cost), 0) / ${krwPerUsd} AS total_cost , 'GCP' COLLATE utf8mb4_unicode_ci AS csp FROM gcp_billing_raw raw LEFT JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid WHERE raw.invoice_month = #{year_month}
AND COALESCE(sm.service_cd COLLATE utf8mb4_uca1400_ai_ci, raw.service_cd, 'undefined') IN
#{selectedProject}
GROUP BY CASE WHEN sm.service_type = 'K8S' THEN 'Kubernetes Engine' ELSE raw.service_description END ) AS all_services GROUP BY service_name, csp -- 같은 이름이 여러 블록에서 나오면(예: NKS 관리비 + NKS 노드) 한 줄로 합산 HAVING SUM(total_cost) > 0 ORDER BY bill DESC LIMIT 5

SELECT childProductCode , SUM(bill) AS bill , SUM(unit) AS unit , csp FROM ( -- AWS VM 데이터 (service_type = 'VM') SELECT COALESCE(SUM(co.lineitem_unblendedcost), 0) AS bill , 'VM' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT co.lineitem_resourceid) AS unit , 'AWS' COLLATE utf8mb4_unicode_ci AS csp FROM tbl_table_billing_detail_${year_month} co INNER JOIN servicegroup_meta sm ON co.lineitem_resourceid COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AWS' AND sm.service_type = 'VM' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
AND 1=0
UNION ALL
-- AWS K8S 데이터 (service_type = 'K8S') SELECT COALESCE(SUM(co.lineitem_unblendedcost), 0) AS bill , 'K8S' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT co.lineitem_resourceid) AS unit , 'AWS' COLLATE utf8mb4_unicode_ci AS csp FROM tbl_table_billing_detail_${year_month} co INNER JOIN servicegroup_meta sm ON co.lineitem_resourceid COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AWS' AND sm.service_type = 'K8S' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
AND 1=0
UNION ALL
-- AWS Object Storage 데이터 (service_type = 'OBJECT_STORAGE', CUR lineitem_resourceid = 버킷명) SELECT COALESCE(SUM(co.lineitem_unblendedcost), 0) AS bill , 'Object Storage' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT co.lineitem_resourceid) AS unit , 'AWS' COLLATE utf8mb4_unicode_ci AS csp FROM tbl_table_billing_detail_${year_month} co INNER JOIN servicegroup_meta sm ON co.lineitem_resourceid COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AWS' AND sm.service_type = 'OBJECT_STORAGE' WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
AND 1=0
UNION ALL
-- AWS Others 데이터 (service_type이 VM/K8S/OBJECT_STORAGE가 아닌 것, 메타에 등록된 리소스만) SELECT COALESCE(SUM(co.lineitem_unblendedcost), 0) AS bill , 'Others' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT co.lineitem_resourceid) AS unit , 'AWS' COLLATE utf8mb4_unicode_ci AS csp FROM tbl_table_billing_detail_${year_month} co INNER JOIN servicegroup_meta sm ON co.lineitem_resourceid COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AWS' AND sm.service_type NOT IN ('VM', 'K8S', 'OBJECT_STORAGE') WHERE 1=1
AND sm.service_cd IN
#{selectedProject}
AND co.lineitem_usagestartdate >= #{curMonthStartDate} AND co.lineitem_usageenddate < #{curMonthEndDate}
AND 1=0
UNION ALL
-- Azure VM 데이터 (service_type = 'VM') SELECT COALESCE(SUM(acvd.pre_tax_cost), 0) / ${krwPerUsd} AS bill , 'VM' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT acvd.resource_id) AS unit , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_vm_daily acvd INNER JOIN servicegroup_meta sm ON acvd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND sm.service_type = 'VM' WHERE DATE_FORMAT(acvd.usage_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
