-- AZURE K8S 데이터 (azure_cost_resource_daily, service_type = 'K8S') SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS bill , 'K8S' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT acr.resource_id) AS unit , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 AND sm.service_type = 'K8S' WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
#{selectedProject}
AND 1=0
UNION ALL
-- D-4: Azure Object Storage — Storage Account 단위 행(계정 매핑 ${azureObjStgAccounts}), Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS bill , 'Object Storage' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT acr.resource_id) AS unit , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_resource_daily acr WHERE acr.resource_type = 'OBJECT_STORAGE' AND LOWER(acr.resource_name) IN (${azureObjStgAccounts}) AND DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month} AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'AZURE' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
AND 1=0
UNION ALL
-- AZURE Others 데이터 (azure_cost_resource_daily, service_type NOT IN ('VM', 'K8S', 'OBJECT_STORAGE')) SELECT COALESCE(SUM(acr.pre_tax_cost), 0) / ${krwPerUsd} AS bill , 'Others' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT acr.resource_id) AS unit , 'AZURE' COLLATE utf8mb4_unicode_ci AS csp FROM azure_cost_resource_daily acr INNER JOIN servicegroup_meta sm ON LOWER(acr.resource_id) COLLATE utf8mb4_unicode_ci = LOWER(sm.csp_instanceid) COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'AZURE' AND acr.resource_type != 'OBJECT_STORAGE' -- Object Storage 는 계정 단위 블록(D-4)에서 집계 AND sm.service_type NOT IN ('VM', 'K8S', 'OBJECT_STORAGE') WHERE DATE_FORMAT(acr.usage_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
#{selectedProject}
AND 1=0
UNION ALL
