-- NCP K8S 데이터 (ncp_cost_resource_daily, service_type = 'K8S') SELECT COALESCE(SUM(ncrd.daily_charge_amount), 0) / ${krwPerUsd} AS bill , 'K8S' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT ncrd.resource_id) AS unit , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ncp_cost_resource_daily ncrd INNER JOIN servicegroup_meta sm ON ncrd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' AND sm.service_type = 'K8S' WHERE DATE_FORMAT(ncrd.target_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
