AND sm.service_cd IN
#{selectedProject}
AND 1=0
UNION ALL
-- D-4: NCP Object Storage — 계정 단위(OSSM) 일별 차분 행, Tumblebug OBJECT_STORAGE 메타가 있을 때만 1회 포함 SELECT COALESCE(SUM(ncrd.daily_charge_amount), 0) / ${krwPerUsd} AS bill , 'Object Storage' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT ncrd.resource_id) AS unit , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ncp_cost_resource_daily ncrd WHERE ncrd.resource_type = 'OBJECT_STORAGE' AND DATE_FORMAT(ncrd.target_date, '%Y%m') = #{year_month} AND EXISTS (SELECT 1 FROM servicegroup_meta smo WHERE smo.csp_type = 'NCP' AND smo.service_type = 'OBJECT_STORAGE'
AND smo.service_cd IN
#{selectedProject}
)
AND 1=0
UNION ALL
-- NCP Others 데이터 (ncp_cost_resource_daily, service_type NOT IN ('VM', 'K8S', 'OBJECT_STORAGE')) SELECT COALESCE(SUM(ncrd.daily_charge_amount), 0) / ${krwPerUsd} AS bill , 'Others' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT ncrd.resource_id) AS unit , 'NCP' COLLATE utf8mb4_unicode_ci AS csp FROM ncp_cost_resource_daily ncrd INNER JOIN servicegroup_meta sm ON ncrd.resource_id COLLATE utf8mb4_unicode_ci = sm.csp_instanceid COLLATE utf8mb4_unicode_ci AND sm.csp_type = 'NCP' AND sm.service_type NOT IN ('VM', 'K8S', 'OBJECT_STORAGE') WHERE DATE_FORMAT(ncrd.target_date, '%Y%m') = #{year_month}
AND sm.service_cd IN
#{selectedProject}
AND 1=0
UNION ALL
-- GCP VM (servicegroup_meta.service_type = 'VM', invoice_month 기준, KRW→USD) SELECT COALESCE(SUM(raw.cost), 0) / ${krwPerUsd} AS bill , 'VM' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT raw.csp_instanceid) AS unit , 'GCP' COLLATE utf8mb4_unicode_ci AS csp FROM gcp_billing_raw raw INNER JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.service_type = 'VM' AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid WHERE raw.invoice_month = #{year_month}
AND sm.service_cd COLLATE utf8mb4_uca1400_ai_ci IN
#{selectedProject}
AND 1=0
UNION ALL
-- GCP K8S (servicegroup_meta.service_type = 'K8S', raw.csp_instanceid = GKE 클러스터명, invoice_month 기준, KRW→USD) SELECT COALESCE(SUM(raw.cost), 0) / ${krwPerUsd} AS bill , 'K8S' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT raw.csp_instanceid) AS unit , 'GCP' COLLATE utf8mb4_unicode_ci AS csp FROM gcp_billing_raw raw INNER JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.service_type = 'K8S' AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid WHERE raw.invoice_month = #{year_month}
AND sm.service_cd COLLATE utf8mb4_uca1400_ai_ci IN
#{selectedProject}
AND 1=0
UNION ALL
-- GCP Object Storage (servicegroup_meta.service_type = 'OBJECT_STORAGE', raw.csp_instanceid = GCS 버킷명, invoice_month 기준, KRW→USD) SELECT COALESCE(SUM(raw.cost), 0) / ${krwPerUsd} AS bill , 'Object Storage' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT raw.csp_instanceid) AS unit , 'GCP' COLLATE utf8mb4_unicode_ci AS csp FROM gcp_billing_raw raw INNER JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.service_type = 'OBJECT_STORAGE' AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid WHERE raw.invoice_month = #{year_month}
AND sm.service_cd COLLATE utf8mb4_uca1400_ai_ci IN
#{selectedProject}
AND 1=0
UNION ALL
-- GCP Others (VM/K8S/OBJECT_STORAGE 로 매칭되지 않는 나머지 — 공통/네트워크/라벨없음) SELECT COALESCE(SUM(raw.cost), 0) / ${krwPerUsd} AS bill , 'Others' COLLATE utf8mb4_unicode_ci AS childProductCode , COUNT(DISTINCT raw.csp_instanceid) AS unit , 'GCP' COLLATE utf8mb4_unicode_ci AS csp FROM gcp_billing_raw raw LEFT JOIN servicegroup_meta sm ON sm.csp_type = 'GCP' AND sm.service_type IN ('VM', 'K8S', 'OBJECT_STORAGE') AND sm.csp_instanceid COLLATE utf8mb4_uca1400_ai_ci = raw.csp_instanceid WHERE raw.invoice_month = #{year_month} AND sm.csp_instanceid IS NULL
AND COALESCE(sm.service_cd COLLATE utf8mb4_uca1400_ai_ci, raw.service_cd, 'undefined') IN
#{selectedProject}
AND 1=0
) subquery WHERE bill > 0 OR childProductCode = 'Others' GROUP BY childProductCode, csp ORDER BY bill DESC

